$function$

CREATE OR REPLACE FUNCTION private.sync_public_badge_subscription_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  PERFORM private.sync_public_badge_for_user(COALESCE(NEW.user_id, OLD.user_id));
  IF TG_OP = 'UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    PERFORM private.sync_public_badge_for_user(OLD.user_id);
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$
